curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(json.dumps(ch))
else:
    print(json.dumps(data))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        print(json.dumps(msg, indent=2))
        print('---')
else:
    print(json.dumps(data))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_INC&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    print('Number of messages:', len(data['messages']))
    for msg in data['messages']:
        print(json.dumps(msg, indent=2))
        print('---')
    if 'response_metadata' in data:
        print('Metadata:', json.dumps(data['response_metadata']))
else:
    print(json.dumps(data))
"

